from pathlib import Path
import importlib.util,re,html,shutil
R=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('renderer',R/'renderer.py');mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)
OUT=R.parent/'docs'
import argparse
parser=argparse.ArgumentParser();parser.add_argument('--base',default='');args=parser.parse_args()
BASE=args.base.rstrip('/')
if not re.fullmatch(r'(?:/[a-zA-Z0-9-]+)*',BASE):raise ValueError('Invalid base path')
def with_base(markup):
 return re.sub(r'\b(src|href|data-src)="(/[^"/][^"]*)"',lambda m:f'{m[1]}="{BASE}{m[2]}"',markup)

e=html.escape
CSS='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#08090d;color:#e8ecef;font:400 16px/1.6 Inter,Arial,sans-serif;-webkit-font-smoothing:antialiased}a{color:inherit;text-underline-offset:5px}button{font-family:inherit}img{max-width:100%;height:auto}a:focus-visible,button:focus-visible{outline:2px solid #ecff3e;outline-offset:5px}.shell{width:min(1120px,calc(100% - 64px));margin:auto}.review-chrome{display:flex;justify-content:space-between;align-items:center;gap:30px;padding:25px 32px}.review-chrome img{width:130px;height:auto}.review-chrome nav{display:flex;gap:28px;align-items:center;font-size:10px;text-transform:uppercase;letter-spacing:.08em}.review-chrome a{text-decoration:none}.eyebrow{display:block;color:#ecff3e;text-transform:uppercase;letter-spacing:.16em;font:600 10px/1.5 Inter,sans-serif}.sector__hero{padding:65px 0 55px;max-width:900px}.sector__title,.overview-title{font:700 clamp(38px,5vw,68px)/1.07 Fraunces,Georgia,serif;letter-spacing:-.025em;text-wrap:balance;margin:24px 0}.sector__lede{max-width:63ch;color:#b5b9bd;font-size:19px;line-height:1.65}.sector__case{border-top:1px solid #33363b;padding:65px 0 80px;display:grid;grid-template-columns:5fr 7fr;gap:65px;align-items:start}.sector__cat{font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:#ecff3e}.sector__case-title{font:700 clamp(28px,3vw,39px)/1.14 Fraunces,Georgia,serif;letter-spacing:-.02em;margin:20px 0 24px}.sector__case-text>p{font-size:16px;line-height:1.75;color:#aeb4ba;margin:0}.sector__benefit{border-top:1px solid #33363b;margin-top:32px;padding-top:24px}.sector__benefit-label{color:#ecff3e;text-transform:uppercase;font-size:9px;letter-spacing:.14em}.sector__benefit-list{padding:0;list-style:none;display:grid;gap:12px;font-size:14px;line-height:1.6}.sector__benefit-list li::before{content:'↗';color:#d2df88;margin-right:11px}.sector__viz{margin:0;min-width:0}.review-footer{padding:36px 0 55px;border-top:1px solid #33363b;font-size:11px;color:#929aa1;display:flex;justify-content:space-between;gap:25px}.overview{display:grid;grid-template-columns:5fr 7fr;gap:70px;padding:80px 0 110px}.overview p{color:#aeb4ba;max-width:44ch}.pilot-list{padding-top:12px}.pilot-list>a{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:24px 0;border-bottom:1px solid #33363b;text-decoration:none}.pilot-list strong{font:700 26px/1.2 Fraunces,Georgia,serif}.pilot-list small{display:block;color:#999fa4;font-size:10px;letter-spacing:.04em;margin-top:10px}.pilot-status{border:1px solid #42483f;font-size:9px;padding:4px 7px;color:#c0c8b2;white-space:nowrap}.pilot-list>a:hover strong{color:#ecff3e}.portrait-review{display:grid;grid-template-columns:220px 1fr;gap:45px;align-items:center;border-top:1px solid #33363b;padding:50px 0 80px}.portrait-review img{width:220px;border-radius:4px}.portrait-review h2{font:700 35px/1.1 Fraunces,Georgia,serif}.portrait-review p{color:#aeb4ba;max-width:49ch}.portrait-review .awaiting{font-size:12px;color:#90989e}.pilot-publication-note{max-width:70ch;color:#92999f;font-size:12px;margin:0 0 50px}@media(max-width:760px){.shell{width:calc(100% - 40px)}.review-chrome{padding:20px}.review-chrome img{width:105px}.review-chrome nav{gap:18px;font-size:9px}.sector__hero{padding:45px 0 35px}.sector__lede{font-size:16px}.sector__case{grid-template-columns:1fr;gap:35px;padding:40px 0 55px}.sector__case-title{font-size:31px}.overview{grid-template-columns:1fr;gap:25px;padding:45px 0 65px}.pilot-list strong{font-size:24px}.portrait-review{grid-template-columns:120px 1fr;gap:22px}.portrait-review img{width:120px}.portrait-review h2{font-size:28px}.portrait-review p{font-size:13px}.review-footer{flex-wrap:wrap}}
'''
(OUT/'pilots').mkdir(exist_ok=True)
(OUT/'pilots/review.css').write_text(CSS,encoding='utf-8')
def wrap(c,title,body,lang_link):
 en=c['lang']=='en';back='/pilots/' if en else '/pilots/de/'
 return with_base(f'''<!doctype html><html lang="{c['lang']}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{e(title)} · Follow the Rabbit</title><link rel="stylesheet" href="/fonts/fonts.css"><link rel="stylesheet" href="/pilots/review.css"><link rel="stylesheet" href="/pilot-assets/pilots.css"><script type="module" src="/pilot-assets/pilots.js"></script></head><body><header class="review-chrome"><a href="{back}"><img src="/ftr_logo.svg" alt="Follow the Rabbit"></a><nav><a href="{back}">{'← Pilots' if en else '← Pilotprojekte'}</a><a href="{lang_link}" lang="{'de' if en else 'en'}">{'DE' if en else 'EN'}</a></nav></header><main class="shell">{body}<footer class="review-footer"><span>Follow the Rabbit / {'Pilot review' if en else 'Pilot-Review'}</span><a href="https://followtherabbit.studio/">{'Visit the website' if en else 'Zur Website'} ↗</a></footer></main></body></html>''')
for lang,c in mod.DATA.items():
 en=lang=='en';prefix='/pilots/' if en else '/pilots/de/'
 for item in c['items']:
  all_articles=mod.articles(c);start=all_articles.index(f'<article class="sector pilot-sector" data-sector="{item["id"]}"');end=mod.element_end(all_articles,start,'article');a=all_articles[start:end].replace(f'data-sector="{item["id"]}" hidden',f'data-sector="{item["id"]}"',1).replace('data-src=','src=').replace('<h2 class="sector__title"','<h1 class="sector__title"',1).replace('</h2>','</h1>',1)
  note='' if item.get('deferred') else ('<p class="pilot-publication-note">'+('A pilot preview using illustrative content. It shows the interface and review process, without publishing client findings or operational data.' if en else 'Ein Pilot-Einblick mit illustrativen Inhalten. Gezeigt werden Oberfläche und Prüfschritte, ohne Kundenergebnisse oder Betriebsdaten zu veröffentlichen.')+'</p>')
  dest=OUT/('pilots/'+('' if en else 'de/')+item['id']+'/index.html');dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(wrap(c,item['name'],a+note,('/pilots/de/' if en else '/pilots/')+item['id']+'/'),encoding='utf-8')
 links=''.join(f'<a href="{prefix}{i["id"]}/"><span><strong>{e(i["name"])}</strong><small>{e(i["field"])}</small></span><span class="pilot-status">{e(i["status"])}</span></a>' for i in c['items'])
 portrait=f'''<section class="portrait-review"><img src="/pilot-assets/guillaume.png" alt="Guillaume" width="1224" height="1285"><div><span class="eyebrow">{e(mod.PROFILE['role' if en else 'roleDe'])}</span><h2>Guillaume</h2><p>{e(mod.PROFILE['bioEn' if en else 'bioDe'])}</p></div></section>'''
 body=f'<section class="overview"><div><span class="eyebrow">Projects / {e(c["section"])}</span><h1 class="overview-title">{e(c["intro"])}</h1><p>{e(c["lede"])}</p></div><div class="pilot-list">{links}</div></section>'+portrait
 dest=OUT/('pilots/index.html' if en else 'pilots/de/index.html');dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(wrap(c,c['previewTitle'],body,'/pilots/de/' if en else '/pilots/'),encoding='utf-8')
print('Built focused EN/DE pilot review pages')

fragments=R/'fragments';fragments.mkdir(exist_ok=True)
for lang,c in mod.DATA.items():
 (fragments/f'projects-pilots-{lang}.html').write_text(mod.board(c),encoding='utf-8')
 (fragments/f'pilot-overlays-{lang}.html').write_text(mod.articles(c),encoding='utf-8')
 (fragments/f'guillaume-team-{lang}.html').write_text(mod.team(c),encoding='utf-8')
